const inp = $input.first().json;

const msgData = { telefono: inp.telefono, texto: inp.texto || '', nombreContacto: inp.nombreContacto || '' };
const kbContexto = inp.kbContexto || '';
const configData = { records: [{ fields: inp.configEmpresa || {} }] };
const waConfigData = { records: [{ fields: inp.waConfig || {} }] };
const leadData = { records: inp.leadId ? [{ id: inp.leadId, fields: inp.leadFields || {} }] : [] };
const productosData = { records: (inp.productosRaw || []) };

const config = configData.records?.[0]?.fields || {};
const waConfig = waConfigData.records?.[0]?.fields || {};
const emailVendedor = config.WA_Email_Vendedor || 'risosadmi@gmail.com';
const followup24 = waConfig.WA_FollowUp_24h || '';
const followup72 = waConfig.WA_FollowUp_72h || '';

const leadExistente = leadData.records?.[0];
const leadId = leadExistente?.id || null;
const leadFields = leadExistente?.fields || {};

let datosRecolectados = {
  producto: leadFields.Articulo || null,
  medidas: leadFields['Medidas y Peso'] || null,
  fecha: null,
  tipo_cajon: null,
  proteccion_extra: null,
  correo_contacto: null,
  nombre_cliente: leadFields.Nombre_Contacto || null,
  tipo_flujo: null
};

let notasOriginal = {};
try {
  const notas = leadFields.Notas || '';
  if (notas && notas.trim().startsWith('{')) {
    const stored = JSON.parse(notas);
    notasOriginal = stored;
    if (stored.tipo_cajon)       datosRecolectados.tipo_cajon = stored.tipo_cajon;
    if (stored.correo_contacto)  datosRecolectados.correo_contacto = stored.correo_contacto;
    if (stored.nombre_cliente && !datosRecolectados.nombre_cliente) datosRecolectados.nombre_cliente = stored.nombre_cliente;
    if (stored.proteccion_extra !== null && stored.proteccion_extra !== undefined) datosRecolectados.proteccion_extra = stored.proteccion_extra;
    if (stored.fecha)            datosRecolectados.fecha = stored.fecha;
    if (stored.tipo_flujo)       datosRecolectados.tipo_flujo = stored.tipo_flujo;
  }
} catch(e) {}

const r3 = leadFields['¿Protección adicional?'] || '';
if (r3 === 'true')  datosRecolectados.proteccion_extra = true;
else if (r3 === 'false') datosRecolectados.proteccion_extra = false;

const estado = leadFields.Estado || 'Nuevo';
const cotizacionEnviada = notasOriginal.cotizacion_enviada === true;
const escaladaEnviada = notasOriginal.escalada_enviada === true;
const idiomaGuardado = notasOriginal.idioma || null;
const historialRaw = leadFields.Historial_Mensajes || '';
const historial = historialRaw ? historialRaw.split('\n').slice(-20).join('\n') : '';
const esNuevo = !leadId;

const catalogoProductos = (productosData.records || []).map(r => {
  const f = r.fields;
  return Object.entries(f).find(([k]) => k.includes('Nombre de Servicio'))?.[1] || '';
}).filter(l => l.length > 2).join(', ');

const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes' : 'buenas noches';
const saludo = saludoHora.charAt(0).toUpperCase() + saludoHora.slice(1);
const saludoEN = horaMiami >= 6 && horaMiami < 12 ? 'Good morning' : horaMiami >= 12 && horaMiami < 19 ? 'Good afternoon' : 'Good evening';

const texto = (msgData.texto || '').trim();

// Detectar idioma del MENSAJE ACTUAL
const textoActual = texto.toLowerCase();
const palabrasEN_actual = (textoActual.match(/\b(i|the|you|need|have|want|please|thanks|yes|no|for|and|my|is|are|can|would|like|some|to|of|in|with|it|this|that|hi|hello|good|morning|afternoon|evening|closed|open|crate|inches|inch|need|done|by|next|about|looking|want|send|ship|pack|protection|foam|email|quote|price)\b/g) || []).length;
const palabrasES_actual = (textoActual.match(/\b(quiero|necesito|tengo|hola|gracias|por favor|sí|no|para|con|una|un|que|me|mi|el|la|los|las|de|en|es|son|buenas|buenos|necesito|embalar|cajón|cerrado|abierto|medidas|correo|cotización|precio|protección|espuma|burbuja)\b/g) || []).length;
const isGreeting = /^(hola[sa]?\b|hi\b|buenas\b|buenos\b|hey\b|good\s|morning|afternoon|evening|hello\b)/i.test(texto);
// Lock idioma once detected — only recalculate on greeting or first message
let idiomaConversacion;
if (idiomaGuardado && !isGreeting) {
  idiomaConversacion = idiomaGuardado; // keep locked idioma
} else {
  idiomaConversacion = palabrasEN_actual >= palabrasES_actual ? 'inglés' : 'español';
}

// Saludo en cliente existente = nueva sesión, resetear tipo_flujo y escalada pendiente
if (isGreeting && !esNuevo) {
  datosRecolectados.tipo_flujo = null;
  // Clear pending escalation from previous session
}
const escaladaPendiente = (isGreeting && !esNuevo) ? false : (notasOriginal.escalada_pendiente === true);

// Extracción de nombre en JavaScript — no depender del AI para esto
if (!datosRecolectados.nombre_cliente) {
  const t = texto.trim();
  // "soy Roberto", "me llamo Ana", "my name is Carlos", "I'm Sarah", "is mirtha", "soy yo Mirtha"
  const matchNombre = t.match(/(?:^|\s)(?:soy\s+(?:yo\s+)?|me llamo\s+|my name is\s+|i[' ]?m\s+|is\s+)([A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+(?:\s+[A-ZÁÉÍÓÚÜÑa-záéíóúüñ][a-záéíóúüñA-ZÁÉÍÓÚÜÑ]+)?)/i);
  if (matchNombre) {
    datosRecolectados.nombre_cliente = matchNombre[1].trim();
  } else if (/^[A-ZÁÉÍÓÚÜÑa-záéíóúüñ]+([ -][A-ZÁÉÍÓÚÜÑa-záéíóúüñ]+){0,2}$/.test(t) && t.length >= 3 && t.length <= 40 && !t.includes('?')) {
    // Mensaje que ES únicamente un nombre (1-3 palabras, solo letras, sin signos de pregunta)
    datosRecolectados.nombre_cliente = t.replace(/ \w/g, c => c.toUpperCase());
  }
}

const cleanCheck = v => {
  if (typeof v === 'boolean') return v;
  if (!v || ['desconocido','null','undefined'].includes(String(v).toLowerCase().trim())) return null;
  return v;
};

const calcProximoPaso = d => {
  if (cotizacionEnviada)                     return 'POST_COTIZACION';
  if (escaladaEnviada)                       return 'CONSULTA_REGISTRADA';
  if (escaladaPendiente)                     return 'FLUJO_CONSULTA';  // mantener en flujo consulta hasta tener correo
  if (esNuevo && !d.nombre_cliente)          return 'PRIMER_CONTACTO';
  if (!cleanCheck(d.nombre_cliente))         return 'PEDIR_NOMBRE';
  if (!d.tipo_flujo)                         return 'IDENTIFICAR_NECESIDAD';
  if (d.tipo_flujo === 'consulta')           return 'FLUJO_CONSULTA';
  if (!cleanCheck(d.producto))               return 'PEDIR_PRODUCTO';
  if (!cleanCheck(d.medidas))                return 'PEDIR_MEDIDAS';
  if (!cleanCheck(d.correo_contacto))        return 'PEDIR_CORREO';
  if (!cleanCheck(d.tipo_cajon))             return 'PEDIR_TIPO_CAJON';
  if (d.proteccion_extra === null || d.proteccion_extra === undefined) return 'PEDIR_PROTECCION';
  if (!cleanCheck(d.fecha))                  return 'PEDIR_FECHA';
  return 'LISTO_PARA_COTIZAR';
};

const proximoPaso = calcProximoPaso(datosRecolectados);
const todosRecolectados = proximoPaso === 'LISTO_PARA_COTIZAR';

const dimensiones = datosRecolectados.medidas ? (() => {
  const nums = (datosRecolectados.medidas || '').match(/(\d+(?:\.\d+)?)/g);
  return nums && nums.length >= 3
    ? { largo: parseFloat(nums[0]), ancho: parseFloat(nums[1]), alto: parseFloat(nums[2]) }
    : null;
})() : null;

// Instrucción simple por paso — la IA maneja todas las variantes
const pasoInstrucciones = {
  PRIMER_CONTACTO:       idiomaConversacion === 'inglés'
    ? `Your response MUST start with: "${saludoEN}, I'm Marco from Crating Express." Then in the SAME message: extract ALL data already mentioned by the client (name, product, measurements, date, etc.), confirm what you extracted, and ask ONLY for what is still missing. If name is missing, ask "Who am I speaking with?" — do NOT ask "how can I help you?" if they already said what they need.`
    : `Tu respuesta DEBE comenzar con: "${saludo}, soy Marco de Crating Express." Luego en EL MISMO mensaje: extrae TODOS los datos que el cliente ya mencionó (nombre, producto, medidas, fecha, etc.), confirma lo que entendiste, y pregunta SOLO lo que falta. Si falta el nombre, pregunta "¿Con quién tengo el gusto?" — NO preguntes "¿en qué puedo ayudarte?" si ya dijeron lo que necesitan.`,

  CONSULTA_REGISTRADA:   `La consulta ya fue registrada. Di: "Ya pasamos tu consulta al equipo, te contactarán en breve. ¿Hay algo más en lo que pueda ayudarte?". NO hagas más preguntas de datos ni recopiles información adicional.`,
  PEDIR_NOMBRE:          `El cliente acaba de responder con su nombre. Extráelo en el campo 'nombre'. En tu respuesta: salúdalo por su nombre ('Hola [nombre], un gusto.') y continúa inmediatamente con lo que el cliente planteó antes — NO vuelvas a preguntar el nombre, NO preguntes '¿en qué puedo ayudarte?' si ya dijeron lo que necesitan. Si no hay contexto previo, pregunta en qué puedes ayudar.`,
  IDENTIFICAR_NECESIDAD: `Revisa el historial y el mensaje actual. Si el cliente ya hizo una pregunta o mencionó lo que necesita, RESPÓNDELA directamente y marca el intento (cotizacion o consulta). NO preguntes "¿en qué puedo ayudarte?" si el cliente ya dijo lo que quiere.`,
  FLUJO_CONSULTA:        idiomaConversacion === 'inglés'
    ? `Answer the client's question using available catalog, policies, and company info.
If the question is OUTSIDE your knowledge or requires human confirmation (specific dates, pricing, discounts, contracts, commercial accounts, volume agreements, negotiations, claims, warranties, special conditions): in the same message say you're passing the inquiry AND ask for email if you don't have it (e.g. "Got it. What's your email so our team can reach you?"). If you already have their email, say: "Perfect, I'm passing your inquiry to our team — someone will be in touch shortly." and mark escalada=true. NEVER invent who handles what or assume you can resolve something not in your catalog.
If they ask for a quote or want to pack something, mark intent=cotizacion.
DAMAGE CLAIMS: If client mentions damage or claim on existing order: first message show empathy + policy; second message direct to cratingexpress01@gmail.com with photos, mark escalada=true. Max 2 messages.`
    : `Responde la pregunta del cliente con la información disponible del catálogo, políticas y empresa.
Si la pregunta está FUERA de tu conocimiento o requiere confirmación humana (disponibilidad de fechas específicas, precios, descuentos, contratos, acuerdos comerciales, términos de negociación, quién atiende qué, reclamos, garantías, especificaciones no documentadas, condiciones especiales): en el mismo mensaje di que vas a pasar la consulta Y pide el correo si no lo tienes (ej: "Entendido. ¿Cuál es tu correo para que el equipo te contacte?"). Si ya tienes el correo, di: "Listo, voy a pasar tu consulta a nuestro equipo — un agente te contactará en breve." y marca escalada=true. NUNCA inventes quién atiende ni asumas que puedes resolver algo que no está en tu catálogo.
Si después pide cotización o quiere embalar algo, marca intento=cotizacion.
QUEJAS Y DAÑOS — REGLA ABSOLUTA: Si el cliente menciona daño, cajón roto, mercancía afectada, garantía o reclamo sobre un pedido existente: en el PRIMER mensaje expresa empatía y da la política ('Lamentamos lo sucedido. Evaluamos todos los casos y respondemos formalmente.'); en el SEGUNDO mensaje dirige al cliente a cratingexpress01@gmail.com con fotos del daño y marca escalada=true. NO sigas más allá de 2 mensajes.`,
    PEDIR_PRODUCTO:        `Si el cliente menciona el artículo en este mensaje, extráelo en "producto". Si menciona una cantidad (ej: "15 botellas", "3 cuadros"), extráela en "cantidad". Si no hay artículo, pregunta qué necesita embalar y cuántas unidades.`,
  PEDIR_MEDIDAS:         `Si el mensaje contiene medidas (números), extráelas en "medidas" y confirma con una frase corta.
Si el cliente dice que NO tiene las medidas aún, o solo quiere información/precio general: NO insistas — en el mismo mensaje di que vas a pasar la consulta a un agente Y pide su correo si aún no lo tienes (ej: "Entendido. ¿Cuál es tu correo para que el equipo te contacte con opciones de precio?"). Si ya tienes el correo, di directamente: "Listo, voy a pasar tu consulta a nuestro equipo — un agente te contactará en breve." y marca escalada=true.
Si no hay medidas ni indicación de que no las tiene, pregunta exactamente: "¿Cuáles son las medidas en pulgadas? (Largo × Ancho × Alto)" — NUNCA menciones centímetros.`,
  PEDIR_TIPO_CAJON:      `Si el cliente pide recomendación o no sabe, recomienda el cajón cerrado (más seguro, ISPM-15 incluido). Si indica preferencia, extráela en "tipo_cajon".`,
  PEDIR_PROTECCION:      `Pregunta si necesita protección interior (foam, burbuja, esquineras) — tiene costo adicional. Si el cliente dice cualquier afirmativo ('sí', 'agrégala', 'la más segura', 'sí por favor', etc.) → extrae proteccion_extra=true y avanza a la fecha SIN pedir confirmación. Si el cliente dice cualquier negativo ('no', 'que no', 'no gracias', 'sin protección', 'solo el cajón', 'nada extra', 'así está bien', 'no necesito') → extrae proteccion_extra=false y avanza a la fecha. Si el cliente hace una pregunta diferente → respóndela brevemente (1 oración) y luego pregunta sobre la protección de nuevo.`,
  PEDIR_FECHA:           `Pregunta para cuándo necesita el embalaje. Si ya lo mencionó, extráelo en "fecha". NUNCA preguntes sobre recogida, entrega, dirección ni logística.`,
  LISTO_PARA_COTIZAR:    `Di EXACTAMENTE este texto y nada más: 'Dame un momento para calcular el precio... 🔄'. NO hagas preguntas. NO menciones cotización, vendedor ni procedimientos. Solo ese mensaje.`,
  PEDIR_CORREO:          idiomaConversacion === 'inglés'
    ? `Ask for the client's email. Say: "What's your email so we can follow up?" If already in message, extract in 'correo', confirm with "Got it" and in THE SAME message ask the next pending question (type of crate or protection). Do NOT mention sending a quote yet.`
    : `Pide el correo del cliente. Di: "¿Cuál es tu correo para darte seguimiento?" Si ya está en el mensaje, extráelo en 'correo', confirma con "Anotado" y en EL MISMO mensaje pregunta el siguiente dato pendiente (tipo de cajón o protección). NO menciones cotización todavía.`,
  POST_COTIZACION:       `Revisa el MENSAJE ACTUAL del cliente:
- Si el cliente ACEPTA (dice sí, si, sisi, ok, claro, yes, dale, please, por favor, mándame, send it, etc.) → confirma brevemente: "Perfecto, te llega la cotización formal a [correo]. ¡Cualquier duda estamos aquí!" y NO hagas más preguntas.
- Si el cliente se DESPIDE (dice gracias, ok gracias, buen día, bye, hasta luego, chao, good day, thank you, etc.) → responde solo: "¡Hasta luego! 👋" y no agregues nada más.
- Si el cliente aún NO ha respondido o pregunta por el precio → recuérdale el estimado y pregunta si desea la cotización formal a su correo.
- NUNCA repitas la misma respuesta dos veces. No inventes un precio nuevo.`
};

const instruccionPaso = pasoInstrucciones[proximoPaso] || 'Responde al cliente de forma útil.';

const sistemaIA = `Eres Marco, asistente de ventas de Crating Express en Miami. Responde SIEMPRE en ${idiomaConversacion}. Directo, conciso, coloquial — Miami va rápido. Máximo 2 oraciones por mensaje. NUNCA uses: "Genial", "Excelente elección", "Un placer", "Con mucho gusto" — suenan a call center. Varía las confirmaciones — nunca uses la misma dos veces seguidas: "Listo.", "Anotado.", "Ok.", "Entendido.", "Perfecto." NUNCA repitas info que el cliente ya dio.
NUNCA preguntes sobre recogida, entrega, dirección ni método de envío — eso no es parte del flujo.
Si el cliente hace una pregunta fuera del flujo mientras se recopilan datos, respóndela en 1 oración y luego continúa con la pregunta pendiente en el mismo mensaje.
REGLA DE ESCALADA INMEDIATA: Si el cliente pide hablar con alguien más, un supervisor, ventas, un humano, o dice que no está listo para dar datos ("es para futuro", "solo quiero términos", "contacta a alguien", etc.) → PARA todas las preguntas, pide su correo si no lo tienes ("¿A qué correo te contactamos?") y marca escalada=true. NO hagas más preguntas de datos.
NUNCA ASUMAS información que no tienes: no inventes quién atiende contratos, no digas "te comunicas conmigo", no afirmes disponibilidad de fechas, precios, descuentos ni condiciones que no están en el catálogo. Si no sabes la respuesta exacta → escala. Inventar información es peor que no saber.
NUNCA termines un mensaje sin hacer una pregunta al cliente — excepto en LISTO_PARA_COTIZAR o POST_COTIZACION. Si confirmaste un dato, inmediatamente pregunta el siguiente pendiente según el contexto.
CATÁLOGO: ${catalogoProductos || 'cajones cerrados, jaulas, paletas a medida, cunas, plataformas en contenedor, embalaje para ferias'}
ISPM-15 incluido en todos los cajones sin costo extra. Las medidas SIEMPRE en pulgadas — NUNCA menciones centímetros ni metros.

Responde ÚNICAMENTE con JSON válido (sin markdown, sin texto antes o después):
{"intento":"cotizacion|consulta|saludo|otro","nombre":null,"producto":null,"cantidad":null,"medidas":null,"tipo_cajon":null,"proteccion_extra":null,"fecha":null,"correo":null,"escalada":null,"respuesta":"mensaje para el cliente"}

Valores válidos para tipo_cajon: cajones_cerrados, jaulas, palets_medida, cunas, plataformas_contenedor, embalaje_ferias
Extrae datos del mensaje actual Y del historial si aún no fueron capturados. Si un dato ya está en DATOS YA RECOLECTADOS, no lo pidas de nuevo. Usa null solo si el dato genuinamente no aparece en ningún lado.`;

const usuarioIA = `CLIENTE: ${datosRecolectados.nombre_cliente || '(desconocido)'}
DATOS YA RECOLECTADOS (no pedir de nuevo):
- Producto: ${datosRecolectados.producto || '—'}
- Medidas: ${datosRecolectados.medidas || '—'}
- Correo: ${datosRecolectados.correo_contacto || '—'}
- Tipo cajón: ${datosRecolectados.tipo_cajon || '—'}
- Protección extra: ${datosRecolectados.proteccion_extra ?? '—'}
- Fecha: ${datosRecolectados.fecha || '—'}
${historial ? '\nHISTORIAL RECIENTE:\n' + historial : ''}
${kbContexto ? '\nKB RELEVANTE:\n' + kbContexto : ''}

MENSAJE ACTUAL DEL CLIENTE: "${texto}"

PASO: ${proximoPaso}
INSTRUCCIÓN: ${instruccionPaso}`;

return [{json: {
  telefono: msgData.telefono,
  texto,
  nombreContacto: msgData.nombreContacto,
  leadId,
  leadFields,
  estado,
  historial,
  esNuevo,
  emailVendedor,
  followup24,
  followup72,
  datosRecolectados,
  notasOriginal,
  cotizacionEnviada,
  escaladaEnviada,
  idiomaConversacion,
  escaladaPendiente,
  proximoPaso,
  todosRecolectados,
  dimensiones,
  tipoCajaApi: datosRecolectados.tipo_cajon || null,
  saludoHora,
  sistemaIA,
  usuarioIA,
  catalogoFinal: catalogoProductos,
  productosRaw: inp.productosRaw || []
}}];
